}

function cumulativeLengths(points) {
  const arr = [0];
  for (let i = 1; i < points.length; i++) {
    const prev = points[i - 1];
    const cur = points[i];
    arr[i] = arr[i - 1] + Math.hypot(cur.x - prev.x, cur.y - prev.y);
