        attacker,
        target: defender,
        hit: false,
        style: ammoStyle,
        projectileSpeed,
        from: { x: apos.x, y: apos.y },
        to: { x: dpos.x, y: dpos.y },
        missTo,
      });
      world.remove(attacker, RangedAttackIntent);
      continue;
    }

