      }
      case "rules.dropItem": {
        const { itemId = 0, count = null } = action.payload || {};
        if (!Number.isInteger(itemId) || itemId <= 0) break;

        const intent = { itemId };
        if (Number.isFinite(count) && count > 0) intent.count = count;
        world?.add?.(actorId, DropIntent, intent);
        world?.tick?.(1);
