        break;
      }
      case "rules.forgeAtAnvil": {
        const { anvilId = 0, recipe = "" } = action.payload || {};
        if (!Number.isInteger(anvilId) || anvilId <= 0) break;
        const recipeKey = String(recipe || "").trim().toLowerCase();
        if (!recipeKey) break;
