        const actorPos = world?.get?.(actorId, Position);
        if (!actorPos) break;
        const eq = world?.get?.(actorId, Equipment);
        const rangedId = Number(eq?.ranged || 0) | 0;
        const rangedInfo = rangedId > 0 ? world?.get?.(rangedId, ItemInfo) : null;
        if (!rangedInfo) {
