  if (typeof value === "string" && value) return true;
  if (!value || typeof value !== "object" || Array.isArray(value)) return false;
  const key = value.ref ?? value.script ?? value.key ?? value.id ?? "";
  return typeof key === "string" && key.length > 0;
}

