 * @returns {boolean}
 */
function stripIntents(world, id, intents) {
  let removed = false;
  for (let i = 0; i < intents.length; i++) {
    if (world.has(id, intents[i])) {
      try { world.remove(id, intents[i]); } catch {}
      removed = true;
    }
  }
  return removed;
}

