 * Stale entities are cleaned up lazily.
 * @param {import('../../lib/ecs-js/index.js').World} world
 * @param {number} x0
 * @param {number} y0
 * @param {number} x1
 * @param {number} y1
 * @param {(id:number, pos:{x:number,y:number})=>void} cb
