const AMMO_PIERCING_ARROW_ACTOR_IMPACT = "ammo:piercingArrows:onProjectileActorImpact";
const AMMO_BODKIN_ARROW_ACTOR_IMPACT = "ammo:bodkinArrows:onProjectileActorImpact";
