registerScript(AMMO_FIRE_ARROW_ACTOR_IMPACT, {
  [ScriptVerb.ProjectileActorImpact]: (_world, ctx) => {
    const extra = ctx.rollDice("1d4");
    if (extra > 0) ctx.addDamage(extra);
    ctx.deferResolved((resolvedCtx) => {
