  assertEquals(String(hit?.projectileKind || ''), 'arrow');
  assert(Math.abs(Number(hit?.impactVector?.dx || 0) - 1) < 1e-6, `impactVector.dx should face target, got ${Number(hit?.impactVector?.dx || 0)}`);
